import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../components/Toast';

export default function Register() {
  const [form, setForm] = useState({
    fullName: '',
    email: '',
    password: '',
    phone: '',
    role: 'JOB_SEEKER',
  });
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { register } = useAuth();
  const { addToast } = useToast();
  const navigate = useNavigate();

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const setRole = (role) => setForm((prev) => ({ ...prev, role }));

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await register(form);
      addToast('Account created successfully! Welcome aboard.', 'success');
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Registration failed.');
      addToast('Registration failed.', 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-fullscreen-container">
      <div className="auth-split-box">
        {/* Left Side: Brand Promo / Showcase */}
        <div className="auth-feature-side">
          <div className="auth-brand-badge">⚡ ResumeCraft Pro</div>
          <h2 className="auth-feature-title">Start Crafting Your Standout Career Profile.</h2>
          <p className="auth-feature-desc">
            Join thousands of professionals creating beautiful, high-converting resumes and landing positions at top companies.
          </p>

          <div className="auth-perks-list">
            <div className="perk-item">
              <span className="perk-icon">⚡</span>
              <div>
                <strong>AI & Power Verbs Assistant</strong>
                <p>One-click action verbs tailored to showcase leadership, engineering, and impact.</p>
              </div>
            </div>
            <div className="perk-item">
              <span className="perk-icon">🎯</span>
              <div>
                <strong>Verified Recruiter Discovery</strong>
                <p>Optionally make your resume searchable to connect directly with hiring managers.</p>
              </div>
            </div>
            <div className="perk-item">
              <span className="perk-icon">🔒</span>
              <div>
                <strong>Privacy & Local Security</strong>
                <p>You control who sees your career documents and contact information.</p>
              </div>
            </div>
          </div>
        </div>

        {/* Right Side: Registration Form */}
        <div className="auth-form-side">
          <form className="auth-card-modern" onSubmit={handleSubmit}>
            <div className="auth-card-header">
              <h3>Create Your Account</h3>
              <p>Get started with free access to templates & real-time editor</p>
            </div>

            {error && <div className="error-banner">{error}</div>}

            {/* Interactive Role Switcher Cards */}
            <div className="role-switcher-container">
              <label className="field-label-sm">I want to:</label>
              <div className="role-cards-grid">
                <div
                  className={`role-option-card ${form.role === 'JOB_SEEKER' ? 'active' : ''}`}
                  onClick={() => setRole('JOB_SEEKER')}
                >
                  <span className="role-icon">💼</span>
                  <div className="role-text">
                    <strong>Build Resumes</strong>
                    <span>Job Seeker</span>
                  </div>
                </div>

                <div
                  className={`role-option-card ${form.role === 'RECRUITER' ? 'active' : ''}`}
                  onClick={() => setRole('RECRUITER')}
                >
                  <span className="role-icon">🔍</span>
                  <div className="role-text">
                    <strong>Hire Talent</strong>
                    <span>Recruiter</span>
                  </div>
                </div>
              </div>
            </div>

            <div className="auth-field-group">
              <label>Full Legal Name</label>
              <div className="input-icon-wrapper">
                <span className="input-icon">👤</span>
                <input
                  name="fullName"
                  value={form.fullName}
                  onChange={handleChange}
                  placeholder="e.g. Richard Sanchez"
                  required
                />
              </div>
            </div>

            <div className="auth-field-group">
              <label>Email Address</label>
              <div className="input-icon-wrapper">
                <span className="input-icon">✉️</span>
                <input
                  type="email"
                  name="email"
                  value={form.email}
                  onChange={handleChange}
                  placeholder="name@company.com"
                  required
                />
              </div>
            </div>

            <div className="auth-field-group">
              <label>Phone Number (Optional)</label>
              <div className="input-icon-wrapper">
                <span className="input-icon">📞</span>
                <input
                  name="phone"
                  value={form.phone}
                  onChange={handleChange}
                  placeholder="+1 (555) 000-0000"
                />
              </div>
            </div>

            <div className="auth-field-group">
              <label>Password</label>
              <div className="input-icon-wrapper">
                <span className="input-icon">🔒</span>
                <input
                  type={showPassword ? 'text' : 'password'}
                  name="password"
                  value={form.password}
                  onChange={handleChange}
                  placeholder="Create a strong password"
                  required
                />
                <button
                  type="button"
                  className="btn-password-toggle"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? '🙈' : '👁️'}
                </button>
              </div>
            </div>

            <button type="submit" className="btn-auth-submit" disabled={loading}>
              {loading ? 'Creating Account…' : 'Create Free Account →'}
            </button>

            <div className="auth-card-footer">
              <p>Already have an account? <Link to="/login" className="auth-link-bold">Sign In</Link></p>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}
